@rendermode InteractiveServer
@using sv_69fbda38e03f4076bca5f2083607b4c0.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector d-inline-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect" class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@using sv_69fbda38e03f4076bca5f2083607b4c0.Services
@inject InventoryAlertService AlertService
@inject WarehouseStateService WarehouseState
@implements IDisposable

<span class="alert-badge position-relative">
    <span class="bi bi-exclamation-triangle-fill-nav-menu" aria-hidden="true"></span>
    @if (_count > 0)
    {
        <span class="badge bg-danger rounded-pill">@_count</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
</span>

@code {
    private int _count;

    protected override void OnInitialized()
    {
        _count = AlertService.LatestLowStockCount;
        AlertService.OnAlertDataChanged += OnAlertDataChanged;
        WarehouseState.OnChange += OnWarehouseChanged;
    }

    private void OnAlertDataChanged()
    {
        InvokeAsync(() =>
        {
            _count = AlertService.LatestLowStockCount;
            StateHasChanged();
        });
    }

    private void OnWarehouseChanged()
    {
        InvokeAsync(() =>
        {
            _count = AlertService.LatestLowStockCount;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
        WarehouseState.OnChange -= OnWarehouseChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@using sv_69fbda38e03f4076bca5f2083607b4c0.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="lead">
    Viewing: <strong>@GetCurrentWarehouseName()</strong>
</p>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text display-6">
            @if (_lowStockCount > 0)
            {
                <span class="text-danger">⚠ @_lowStockCount items below minimum</span>
            }
            else
            {
                <span class="text-success">✓ All stock levels OK</span>
            }
        </p>
        <small class="text-muted">Polling every 10 seconds. Last check: @_lastCheck.ToString("HH:mm:ss")</small>
    </div>
</div>

@code {
    private int _lowStockCount;
    private DateTime _lastCheck = DateTime.Now;
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        _lowStockCount = AlertService.LatestLowStockCount;
        AlertService.OnAlertDataChanged += OnAlertDataChanged;
        WarehouseState.OnChange += OnWarehouseChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch and start polling
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            while (await timer.WaitForNextTickAsync(token))
            {
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            }
        }, token);
    }

    private void OnAlertDataChanged()
    {
        InvokeAsync(() =>
        {
            _lowStockCount = AlertService.LatestLowStockCount;
            _lastCheck = DateTime.Now;
            StateHasChanged();
        });
    }

    private async void OnWarehouseChanged()
    {
        // Immediately refresh data for the new warehouse and restart polling
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        StartPolling();
    }

    private string GetCurrentWarehouseName()
    {
        var wh = WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId);
        return wh == default ? WarehouseState.CurrentWarehouseId : wh.Name;
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
        WarehouseState.OnChange -= OnWarehouseChanged;
    }
}

@rendermode InteractiveServer
@using sv_69fbda38e03f4076bca5f2083607b4c0.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector d-inline-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect" class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

